const allowed: Record<GltfTopLevelFamily, readonly (keyof GltfDiff)[]> = { scenes: ['scene','scenes'], nodes: ['nodes','scenes','skins','animations'], meshes: ['meshes','nodes'], accessors: ['accessors','meshes','skins','animations'], bufferViews: ['bufferViews','accessors','images'], buffers: ['buffers','bufferBytes','bufferViews'], materials: ['materials','meshes'], textures: ['textures','materials'], images: ['images','textures'], samplers: ['samplers','textures'], skins: ['skins','nodes'], animations: ['animations'], cameras: ['cameras','nodes'] };
